CREATE TABLE prestamos_documentos (id INT UNSIGNED NOT NULL AUTO_INCREMENT,contribuyente_id INT UNSIGNED NOT NULL,credito VARCHAR(24) NOT NULL,fecha_factura DATE NOT NULL,fecha_pago DATE NOT NULL,titulo VARCHAR(160) NOT NULL,archivo CHAR(68) NOT NULL,sha256 CHAR(64) NOT NULL,datos LONGTEXT NOT NULL,actor_id INT UNSIGNED NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY prestamo_pdf(contribuyente_id,sha256),UNIQUE KEY prestamo_corte(contribuyente_id,credito,fecha_factura),CONSTRAINT prestamo_titular_fk FOREIGN KEY(contribuyente_id) REFERENCES contribuyentes(id),CONSTRAINT prestamo_datos_json CHECK(JSON_VALID(datos))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
